<?php
use App\Models\AlumniPeserta;
use App\Services\AlumniWorkflowService;
use Livewire\Attributes\Computed;
use Livewire\Attributes\Layout;
use Livewire\Attributes\Title;
use Livewire\Attributes\Url;
use Livewire\Component;
use Livewire\WithPagination;
new #[Layout('layouts.app'), Title('Kurasi Alumni')] class extends Component { use WithPagination; #[Url] public string $search=''; #[Url(as:'kurasi')] public string $kurasi='menunggu'; public ?int $selectedId=null; public string $catatan=''; public function mount(): void {} public function updatedSearch(): void {$this->resetPage();} public function updatedKurasi(): void {$this->resetPage();} #[Computed] public function participants(){return AlumniPeserta::query()->with('activeVideo')->when($this->search,fn($q)=>$q->where(fn($nested)=>$nested->where('nama_lengkap','like','%'.$this->search.'%')->orWhereHas('activeVideo',fn($v)=>$v->where('original_name','like','%'.$this->search.'%'))))->when($this->kurasi,fn($q)=>$q->where('status_kurasi',$this->kurasi))->latest('registered_at')->paginate(12);} #[Computed] public function selected():?AlumniPeserta{return $this->selectedId?AlumniPeserta::query()->with(['activeVideo','kurasi'=>fn($q)=>$q->latest('diproses_at')])->find($this->selectedId):null;} public function curate(string $status, AlumniWorkflowService $workflow):void { $this->validate(['selectedId'=>['required','exists:alumni_peserta,id'],'catatan'=>['nullable','string','max:2000']]); $workflow->curate(AlumniPeserta::findOrFail($this->selectedId),$status,$this->catatan,(int)auth()->id()); $this->dispatch('toast', type:'success', message:'Status kurasi diperbarui.'); $this->reset('selectedId','catatan'); $this->resetPage(); } };
?>
<div class="space-y-5"><div><flux:heading size="xl">Kurasi Karya</flux:heading><flux:subheading>Tinjau video dan tetapkan status kurasi.</flux:subheading></div><flux:card><div class="grid gap-3 md:grid-cols-3"><flux:input wire:model.live.debounce.400ms="search" placeholder="Cari peserta atau karya…"/><flux:select wire:model.live="kurasi"><option value="">Semua status</option>@foreach(['menunggu','lolos','revisi','ditolak'] as $status)<option value="{{ $status }}">{{ ucfirst($status) }}</option>@endforeach</flux:select><span wire:loading class="self-center text-sm text-zinc-500">Memuat…</span></div></flux:card><flux:card><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="text-xs text-zinc-500"><tr><th class="px-2 py-2">Peserta</th><th class="px-2 py-2">Angkatan</th><th class="px-2 py-2">Karya</th><th class="px-2 py-2">Status</th><th></th></tr></thead><tbody>@forelse($this->participants as $peserta)<tr class="border-t border-zinc-200 dark:border-zinc-800"><td class="px-2 py-2"><p class="font-medium">{{ $peserta->nama_lengkap }}</p><p class="text-xs text-zinc-500">{{ $peserta->whatsapp }}</p></td><td class="px-2 py-2">{{ $peserta->tahun_kelulusan }}</td><td class="px-2 py-2">{{ $peserta->activeVideo?->original_name ?? '—' }}</td><td class="px-2 py-2"><x-alumni.status-badge :status="$peserta->status_kurasi"/></td><td class="px-2 py-2"><button wire:click="set('selectedId',{{ $peserta->id }})" class="text-amber-700">Tinjau</button></td></tr>@empty<tr><td colspan="5" class="px-2 py-10 text-center text-zinc-500">Tidak ada karya.</td></tr>@endforelse</tbody></table></div><div class="mt-4">{{ $this->participants->links() }}</div></flux:card>
@if($this->selected)<flux:card><div class="grid gap-5 xl:grid-cols-2"><div><flux:heading size="lg">{{ $this->selected->nama_lengkap }}</flux:heading><p class="mt-1 text-sm text-zinc-500">{{ $this->selected->kode_registrasi }} · {{ $this->selected->tahun_kelulusan }}</p><div class="mt-4"><x-alumni.video-player :video="$this->selected->activeVideo"/></div>@if($this->selected->activeVideo)<a href="{{ route('alumni.video.download',$this->selected->activeVideo) }}" class="mt-3 inline-block text-sm text-amber-700">Unduh video</a>@endif</div><div><flux:textarea wire:model="catatan" label="Catatan kurator" placeholder="Wajib untuk revisi atau penolakan."/><div class="mt-4 flex flex-wrap gap-2"><flux:button wire:click="curate('lolos')" wire:confirm="Setujui karya ini?" variant="primary">Setujui</flux:button><flux:button wire:click="curate('revisi')" wire:confirm="Minta revisi karya ini?">Minta revisi</flux:button><flux:button wire:click="curate('ditolak')" wire:confirm="Tolak karya ini?" variant="danger">Tolak</flux:button></div><div class="mt-6 space-y-2 text-sm">@foreach($this->selected->kurasi as $history)<p><x-alumni.status-badge :status="$history->status_sesudah"/> {{ $history->catatan }}</p>@endforeach</div></div></div></flux:card>@endif</div>
